sqlMap.insert:
INSERT INTO DebitNotes (Id, NoteNo, ContractId, ContractNo, Period, CompanyId,
  RoomFullCode, TenantName, TotalAmount, TotalReceived, TotalPrepaid, BalanceDue,
  IsHistorical, DueDate, Status, GeneratedAt, BillJobTaskLogId, CreatedBy, CreatedAt)
  VALUES (@Id, @NoteNo, @CId, @CNo, @Period, @CoId,
  @Room, @Tenant, @Amt, 0, 0, @Amt,
  @IsHist, @Due, 'Published', GETUTCDATE(), @TaskLogId, @CBy, GETUTCDATE())

sqlMap.select:
    SELECT c.*, r.FullCode AS RoomFullCode FROM Contracts c LEFT JOIN HousingUnits r ON r.Id = c.RoomId WHERE c.Id = @Id;
SELECT ct.ContractId, ct.TenantId, t.Name AS TenantName, ct.IsPrimary FROM ContractTenants ct INNER JOIN Tenants t ON t.Id = ct.TenantId WHERE ct.ContractId = @Id;
SELECT cf.Id, cf.ContractId, cf.FeeCodeId, fc.Name AS FeeCodeName, fc.Code AS FeeCode, fc.ChargeType,
       cf.BillingMode, cf.Amount, cf.Unit, cf.UnitPrice, cf.IsActive, cf.EffectiveDate, cf.ExpiryDate
FROM ContractFeeConfigs cf LEFT JOIN FeeCodes fc ON fc.Id = cf.FeeCodeId WHERE cf.ContractId = @Id
